 {auto stream=input.createOutputStream();if(!stream||!stream->write(mono.data(),mono.size()*4))throw std::runtime_error("Could not prepare beat-analysis audio");stream->flush();}helperWaiting551=true;if(progress)progress(.15f);juce::ChildProcess process;if(!process.start(juce::StringArray{helper.getFullPathName(),model.getFullPathName(),mel.getFullPathName(),input.getFullPathName(),output.getFullPathName()},0))throw std::runtime_error("Could not start full beat detector");auto started=juce::Time::getMillisecondCounterHiRes();while(process.isRunning()){auto report=output.getSiblingFile(output.getFileName()+".progress");if(auto in=report.createInputStream())if(in->getTotalLength()==4){float done=in->readFloat();if(std::isfinite(done)&&done>=0&&done<=1){helperWaiting551=false;if(progress)progress(.15f+.8f*done);}}if((cancel&&cancel())||juce::Time::getMillisecondCounterHiRes()-started>600000){process.kill();process.waitForProcessToFinish(5000);lastError="Full beat analysis cancelled or timed out";return false;}juce::Thread::sleep(20);}helperWaiting551=false;if(process.getExitCode()!=0)throw std::runtime_error("Small beat detector failed");auto stream=output.createInputStream();if(!stream||stream->readInt()!=0x42543530)throw std::runtime_error("Invalid beat predictions");int count=stream->readInt();if(count<1||count>180001||stream->getTotalLength()!=8+(int64_t)count*8)throw std::runtime_error("Incomplete beat predictions");std::vector<std::array<float,2>> predictions(count);if(stream->read(predictions.data(),count*8)!=count*8)throw std::runtime_error("Truncated beat predictions");
 std::vector<int> beats,downbeats;for(int type=0;type<2;++type){auto& peaks=type?downbeats:beats;for(int f=0;f<count;++f){auto value=predictions[f][type];if(!std::isfinite(value))throw std::runtime_error("Nonfinite beat prediction");if(value<=0)continue;bool maximum=true;for(int k=juce::jmax(0,f-3);k<=juce::jmin(count-1,f+3);++k)if(predictions[k][type]>value)maximum=false;if(maximum&&(peaks.empty()||f-peaks.back()>1))peaks.push_back(f);}}
